import unittest

from ta_emss.utilities.SCFC_parser_lib.interfaces.SCFC_parser_main import ScfcParserMain


class TestScfcParserMain(unittest.TestCase):
    def setUp(self):
        self.converter = ScfcParserMain()

    # def test_parse_arguments(self):
    # self.assertEqual(self.converter.parse_args(["file_path"]).scfc, "file_path")

    # def test_passing_to_vars(self):
    #      self.assertEqual(vars(self.converter.parse_args(["abc", "LNBTS-88=ENB_ID"])),
    #                       {"scfc" : "abc", "to_replace":["LNBTS-88=ENB_ID"],"yaml" : None})

    def test_parse_to_replace_args_to_dict(self):
        self.assertEqual(self.converter.parse_to_replace_args_to_dict(["LNBTS-88=ENB_ID", "LNCEL-1=PCELL"]),
                         {"LNBTS-88": "ENB_ID", "LNCEL-1": "PCELL"})

    def test_change_extension_to_yaml(self):
        self.assertEqual(self.converter.change_extension_to_yaml("/abc/a.d/def..../scfc/yaml/file.xml"), "/abc/a.d/def..../scfc/yaml/file.yaml")


if __name__ == "__main__":
    unittest.main()
